// Builds the Power Automate solution zip in the browser, pre-filled with the customer's values.
// The solution files are generated by flows/build-solution.mjs and loaded on demand (separate chunk).

export interface IFlowPackEnvVar {
  schema: string;
  name: string;
  description: string;
  defaultValue: string;
}

export interface IFlowPackInfo {
  version: string;
  solution: string;
  env: IFlowPackEnvVar[];
  flows: { name: string; description: string }[];
  files: Record<string, string>;
}

let cache: Promise<IFlowPackInfo> | undefined;

/** Loads the embedded solution files (only when an admin opens the download dialog). */
export function loadFlowPack(): Promise<IFlowPackInfo> {
  if (!cache) {
    cache = import(/* webpackChunkName: 'brillienta-flow-pack' */ '../models/flowPack.generated').then(m => ({
      version: m.FLOW_PACK_VERSION, solution: m.FLOW_PACK_SOLUTION, env: m.FLOW_PACK_ENV, flows: m.FLOW_PACK_FLOWS, files: m.FLOW_PACK_FILES
    }));
  }
  return cache;
}

const xmlEsc = (s: string): string => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

/** Returns the solution files with the environment-variable defaults replaced by `values` (schema name → value). */
export function customizeFiles(pack: IFlowPackInfo, values: Record<string, string>): Record<string, string> {
  const out: Record<string, string> = {};
  Object.keys(pack.files).forEach(path => {
    let text = pack.files[path];
    const env = /^environmentvariabledefinitions\/([^/]+)\/environmentvariabledefinition\.xml$/.exec(path);
    if (env && values[env[1]] !== undefined) {
      text = text.replace(/<defaultvalue>[\s\S]*?<\/defaultvalue>/, `<defaultvalue>${xmlEsc(values[env[1]])}</defaultvalue>`);
    } else if (/^Workflows\/.+\.json$/.test(path)) {
      const json = JSON.parse(text);
      const params = json?.properties?.definition?.parameters || {};
      Object.keys(params).forEach(k => {
        const schema = params[k]?.metadata?.schemaName;
        if (schema && values[schema] !== undefined) { params[k].defaultValue = values[schema]; }
      });
      text = JSON.stringify(json, null, 2);
    }
    out[path] = text;
  });
  return out;
}

// ---------------------------------------------------------------- minimal ZIP writer (stored, no compression)

let crcTable: number[] | undefined;
function crc32(data: Uint8Array): number {
  if (!crcTable) {
    crcTable = [];
    for (let n = 0; n < 256; n++) {
      let c = n;
      for (let k = 0; k < 8; k++) { c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1; }
      crcTable[n] = c >>> 0;
    }
  }
  let crc = 0xffffffff;
  for (let i = 0; i < data.length; i++) { crc = crcTable[(crc ^ data[i]) & 0xff] ^ (crc >>> 8); }
  return (crc ^ 0xffffffff) >>> 0;
}

/** Creates a ZIP archive (STORE method, UTF-8 names) from text files. */
export function zipFiles(files: Record<string, string>): Blob {
  const enc = new TextEncoder();
  const now = new Date();
  const dosTime = (now.getHours() << 11) | (now.getMinutes() << 5) | Math.floor(now.getSeconds() / 2);
  const dosDate = ((now.getFullYear() - 1980) << 9) | ((now.getMonth() + 1) << 5) | now.getDate();
  const parts: Uint8Array[] = [];
  const central: Uint8Array[] = [];
  let offset = 0;
  // [Content_Types].xml first, like solutions exported by Power Platform
  const names = Object.keys(files).sort((a, b) => (a === '[Content_Types].xml' ? -1 : b === '[Content_Types].xml' ? 1 : a.localeCompare(b)));
  names.forEach(name => {
    const nameBytes = enc.encode(name);
    const data = enc.encode(files[name]);
    const crc = crc32(data);
    const local = new Uint8Array(30 + nameBytes.length);
    const lv = new DataView(local.buffer);
    lv.setUint32(0, 0x04034b50, true);
    lv.setUint16(4, 20, true);          // version needed
    lv.setUint16(6, 0x0800, true);      // UTF-8 names
    lv.setUint16(8, 0, true);           // stored
    lv.setUint16(10, dosTime, true);
    lv.setUint16(12, dosDate, true);
    lv.setUint32(14, crc, true);
    lv.setUint32(18, data.length, true);
    lv.setUint32(22, data.length, true);
    lv.setUint16(26, nameBytes.length, true);
    lv.setUint16(28, 0, true);
    local.set(nameBytes, 30);
    parts.push(local, data);

    const cen = new Uint8Array(46 + nameBytes.length);
    const cv = new DataView(cen.buffer);
    cv.setUint32(0, 0x02014b50, true);
    cv.setUint16(4, 20, true);
    cv.setUint16(6, 20, true);
    cv.setUint16(8, 0x0800, true);
    cv.setUint16(10, 0, true);
    cv.setUint16(12, dosTime, true);
    cv.setUint16(14, dosDate, true);
    cv.setUint32(16, crc, true);
    cv.setUint32(20, data.length, true);
    cv.setUint32(24, data.length, true);
    cv.setUint16(28, nameBytes.length, true);
    cv.setUint32(42, offset, true);
    cen.set(nameBytes, 46);
    central.push(cen);
    offset += local.length + data.length;
  });
  const centralSize = central.reduce((s, c) => s + c.length, 0);
  const end = new Uint8Array(22);
  const ev = new DataView(end.buffer);
  ev.setUint32(0, 0x06054b50, true);
  ev.setUint16(8, names.length, true);
  ev.setUint16(10, names.length, true);
  ev.setUint32(12, centralSize, true);
  ev.setUint32(16, offset, true);
  return new Blob([...parts, ...central, end] as BlobPart[], { type: 'application/zip' });
}

export function downloadBlob(blob: Blob, fileName: string): void {
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = fileName;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(a.href), 2000);
}

export async function downloadFlowPack(values: Record<string, string>): Promise<string> {
  const pack = await loadFlowPack();
  const fileName = `${pack.solution}_${pack.version.replace(/\./g, '_')}.zip`;
  downloadBlob(zipFiles(customizeFiles(pack, values)), fileName);
  return fileName;
}
